//! Generated-file detection: a whole file is generated when its header says so,
//! when it is a lockfile, or when `.gitattributes` marks it
//! `linguist-generated` — which, as on GitHub, also overrides the other two
//! when it says the file is *not* generated.

use std::path::{Path, PathBuf};

use ignore::Match;
use ignore::gitignore::{Gitignore, GitignoreBuilder};
use tokei::LanguageType;

/// How many leading lines may carry a generated-file marker. Go's
/// `// Code generated … DO NOT EDIT.` may sit anywhere before `package`, so Go
/// reads its whole preamble instead.
const HEADER_LINES: usize = 10;

/// Markers that say a file is generated, matched case-insensitively:
/// `@generated` (Facebook's convention), `DO NOT EDIT` (Go's `Code generated
/// … DO NOT EDIT.`, protoc, and many more), `auto-generated` (and .NET's
/// `<auto-generated>`), and generators' prose.
const MARKERS: &[&str] = &[
    "@generated",
    "do not edit",
    "auto-generated",
    "autogenerated",
    "auto generated",
    "automatically generated",
    "this file is generated",
    "this file was generated",
    "this file has been generated",
];

/// Lockfiles: generated by a package manager, and carrying no header.
const LOCKFILES: &[&str] = &[
    "package-lock.json",
    "npm-shrinkwrap.json",
    "pnpm-lock.yaml",
    "yarn.lock",
    "bun.lock",
    "deno.lock",
    "Cargo.lock",
    "Gemfile.lock",
    "poetry.lock",
    "uv.lock",
    "Pipfile.lock",
    "composer.lock",
    "flake.lock",
    "go.sum",
    "packages.lock.json",
];

/// Whether the file `rel` is a lockfile, by name.
pub fn is_lockfile(rel: &Path) -> bool {
    rel.file_name()
        .and_then(|name| name.to_str())
        .is_some_and(|name| LOCKFILES.contains(&name))
}

/// Whether `text` (a file detected as `lang`) opens with a generated-file
/// marker: one of [`MARKERS`] on a comment line among the first
/// [`HEADER_LINES`] lines (in Go, every line before `package`).
///
/// A comment line starts with one of `lang`'s comment markers, or `*` (a
/// block comment's continuation), or sits inside a block comment or doc
/// string opened on an earlier header line. In a language without comment
/// syntax (JSON), any line counts. Prose formats (tokei's literate languages:
/// Markdown and the like) are never read: a README that talks about
/// generated code is not generated.
pub fn has_header_marker(lang: LanguageType, text: &[u8]) -> bool {
    if lang.is_literate() {
        return false;
    }
    let line_openers: Vec<&str> = lang
        .line_comments()
        .iter()
        .copied()
        .filter(|marker| !marker.is_empty())
        .collect();
    let blocks: Vec<(&str, &str)> = lang
        .multi_line_comments()
        .iter()
        .chain(lang.doc_quotes())
        .copied()
        .filter(|(open, _)| !open.is_empty())
        .collect();
    let no_comments = line_openers.is_empty() && blocks.is_empty();
    let go = lang == LanguageType::Go;

    let header = &text[..header_end(text, if go { usize::MAX } else { HEADER_LINES })];
    let mut open_block: Option<&str> = None;
    for line in String::from_utf8_lossy(header).lines() {
        let line = line.trim_start().trim_start_matches('\u{feff}');
        if go && line.starts_with("package ") {
            break;
        }
        let mut comment = no_comments || open_block.is_some();
        comment |= line_openers.iter().any(|open| line.starts_with(open));
        comment |= !blocks.is_empty() && line.starts_with('*');
        // Track a block opened on this line and still open at its end.
        let mut rest = line;
        loop {
            match open_block {
                Some(close) => match rest.find(close) {
                    Some(at) => {
                        rest = &rest[at + close.len()..];
                        open_block = None;
                    }
                    None => break,
                },
                None => match blocks
                    .iter()
                    .filter_map(|&(open, close)| rest.find(open).map(|at| (at, open, close)))
                    .min_by_key(|&(at, _, _)| at)
                {
                    Some((at, open, close)) => {
                        comment |= rest[..at].trim().is_empty();
                        rest = &rest[at + open.len()..];
                        open_block = Some(close);
                    }
                    None => break,
                },
            }
        }
        if comment {
            let line = line.to_ascii_lowercase();
            if MARKERS.iter().any(|marker| line.contains(marker)) {
                return true;
            }
        }
    }
    false
}

/// The byte offset just past the first `lines` lines of `text`.
fn header_end(text: &[u8], lines: usize) -> usize {
    text.iter()
        .enumerate()
        .filter(|&(_, &b)| b == b'\n')
        .nth(lines.saturating_sub(1))
        .map_or(text.len(), |(at, _)| at + 1)
}

/// The `linguist-generated` rules of every `.gitattributes` in the walk.
#[derive(Default)]
pub struct GitAttributes {
    /// One matcher per `.gitattributes`, deepest directory first. Set
    /// patterns are plain, unset ones negated, so a match says which way the
    /// last applicable line of that file went.
    files: Vec<(PathBuf, Gitignore)>,
}

impl GitAttributes {
    /// Read the `.gitattributes` files among `files` (relative to `root`).
    pub fn load(root: &Path, files: &[PathBuf]) -> Self {
        let mut found: Vec<(PathBuf, Gitignore)> = files
            .iter()
            .filter(|rel| rel.file_name().is_some_and(|name| name == ".gitattributes"))
            .filter_map(|rel| {
                let text = std::fs::read_to_string(root.join(rel)).ok()?;
                let dir = rel.parent().unwrap_or(Path::new("")).to_path_buf();
                Some((dir.clone(), Self::parse(&root.join(&dir), &text)?))
            })
            .collect();
        found.sort_by_key(|(dir, _)| std::cmp::Reverse(dir.components().count()));
        Self { files: found }
    }

    /// Build the matcher for one `.gitattributes` in `dir` (absolute).
    fn parse(dir: &Path, text: &str) -> Option<Gitignore> {
        let mut builder = GitignoreBuilder::new(dir);
        let mut any = false;
        for line in text.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let mut fields = line.split_whitespace();
            let Some(pattern) = fields.next() else {
                continue;
            };
            // gitattributes has no negative patterns; a line that tries is
            // ignored, as git ignores it.
            if pattern.starts_with('!') {
                continue;
            }
            let state = fields.fold(None, |state, attr| match attr {
                "linguist-generated" => Some(true),
                "-linguist-generated" | "!linguist-generated" => Some(false),
                // Linguist reads any value but `false` as set.
                _ => match attr.strip_prefix("linguist-generated=") {
                    Some(value) => Some(value != "false"),
                    None => state,
                },
            });
            let glob = match state {
                Some(true) => pattern.to_string(),
                Some(false) => format!("!{pattern}"),
                None => continue,
            };
            if builder.add_line(None, &glob).is_ok() {
                any = true;
            }
        }
        if !any {
            return None;
        }
        builder.build().ok()
    }

    /// What `.gitattributes` says of the file `rel`: `Some(true)` when marked
    /// `linguist-generated`, `Some(false)` when explicitly unmarked, `None`
    /// when no line applies. The deepest `.gitattributes` with a line for it
    /// decides, and within a file the last such line.
    pub fn generated(&self, root: &Path, rel: &Path) -> Option<bool> {
        let path = root.join(rel);
        for (dir, matcher) in &self.files {
            if !rel.starts_with(dir) {
                continue;
            }
            match matcher.matched(&path, false) {
                Match::Ignore(_) => return Some(true),
                Match::Whitelist(_) => return Some(false),
                Match::None => {}
            }
        }
        None
    }
}

/// Whether the file `rel` (detected as `lang`, holding `text`) is generated:
/// what `.gitattributes` says when it says anything — an explicit unset
/// overrides the rest, as on GitHub — else a lockfile name or a header marker.
pub fn is_generated(
    attributes: &GitAttributes,
    root: &Path,
    rel: &Path,
    lang: LanguageType,
    text: &[u8],
) -> bool {
    attributes
        .generated(root, rel)
        .unwrap_or_else(|| is_lockfile(rel) || has_header_marker(lang, text))
}

#[cfg(test)]
impl GitAttributes {
    fn is_generated(&self, root: &Path, rel: &Path) -> bool {
        self.generated(root, rel) == Some(true)
    }
}

#[cfg(test)]
mod tests {
    use std::path::{Path, PathBuf};

    use tokei::LanguageType;

    use super::{GitAttributes, has_header_marker};

    fn marked(lang: LanguageType, text: &str) -> bool {
        has_header_marker(lang, text.as_bytes())
    }

    #[test]
    fn header_markers() {
        let rust = LanguageType::Rust;
        assert!(marked(rust, "// @generated by build.rs\nfn a() {}\n"));
        assert!(marked(
            LanguageType::Go,
            "// Code generated by protoc-gen-go. DO NOT EDIT.\n\npackage pb\n"
        ));
        assert!(marked(
            LanguageType::Python,
            "# -*- coding: utf-8 -*-\n# Generated by the protocol buffer compiler.  DO NOT EDIT!\n"
        ));
        assert!(marked(
            LanguageType::CSharp,
            "//------\n// <auto-generated>\n//     This code was generated by a tool.\n"
        ));
        assert!(marked(
            LanguageType::C,
            "/*\n * This file is automatically generated.\n */\nint x;\n"
        ));
        assert!(marked(
            LanguageType::Toml,
            "# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\nversion = 4\n"
        ));
        assert!(marked(
            LanguageType::Json,
            "{\n  \"//\": \"auto-generated, do not edit\"\n}\n"
        ));
        assert!(marked(rust, "\u{feff}// @generated\n"));
    }

    /// Markers inside a block comment or doc string opened on an earlier
    /// header line: bindgen, C headers, Python docstrings, HTML comments.
    #[test]
    fn markers_inside_an_open_block() {
        assert!(marked(
            LanguageType::Rust,
            "/* automatically generated by rust-bindgen 0.69.4 */\n\npub const X: u32 = 1;\n"
        ));
        assert!(marked(
            LanguageType::C,
            "/*\n   This file is automatically generated. Do not edit.\n*/\nint x;\n"
        ));
        assert!(marked(
            LanguageType::Python,
            "\"\"\"\nAuto-generated by the client generator.\n\"\"\"\nimport os\n"
        ));
        assert!(marked(
            LanguageType::Html,
            "<!--\n DO NOT EDIT\n-->\n<p></p>\n"
        ));
        // A block that closed before the marker line does not make it a comment.
        assert!(!marked(
            LanguageType::C,
            "/* header */\nconst char *s = \"do not edit\";\n"
        ));
    }

    #[test]
    fn the_header_window_and_go_preamble() {
        let rust = LanguageType::Rust;
        let at_line = |n: usize| format!("{}// @generated\n", "fn a() {}\n".repeat(n - 1));
        assert!(marked(rust, &at_line(10)));
        assert!(!marked(rust, &at_line(11)));
        // Go: anywhere before `package`, and not after it.
        let license = "// Copyright 2024 The Authors.\n//\n".repeat(10);
        let go =
            format!("{license}\n// Code generated by controller-gen. DO NOT EDIT.\n\npackage v1\n");
        assert!(marked(LanguageType::Go, &go));
        assert!(!marked(
            LanguageType::Go,
            "package v1\n\n// Code generated by hand. DO NOT EDIT.\n"
        ));
    }

    #[test]
    fn more_generator_phrasings() {
        let rust = LanguageType::Rust;
        assert!(marked(rust, "// Autogenerated: word_by_word_montgomery\n"));
        assert!(marked(rust, "// This file was generated by wit-bindgen.\n"));
        assert!(marked(
            rust,
            "// THIS FILE IS GENERATED, edit the template\n"
        ));
    }

    /// Prose formats talk about generated code without being generated.
    #[test]
    fn prose_formats_are_not_read() {
        assert!(!marked(
            LanguageType::Markdown,
            "# Bindings\n\nThese are automatically generated; do not edit.\n"
        ));
    }

    #[test]
    fn lockfiles_by_name() {
        use super::is_lockfile;
        for name in [
            "package-lock.json",
            "web/pnpm-lock.yaml",
            "Cargo.lock",
            "go.sum",
        ] {
            assert!(is_lockfile(Path::new(name)), "{name}");
        }
        assert!(!is_lockfile(Path::new("lock.json")));
        assert!(!is_lockfile(Path::new("src/package-lock.json.rs")));
    }

    #[test]
    fn markers_outside_the_header_or_a_comment_do_not_count() {
        let rust = LanguageType::Rust;
        assert!(
            !marked(rust, "const NOTE: &str = \"DO NOT EDIT\";\n"),
            "code, not a comment"
        );
        assert!(!marked(rust, "//! Reads generated files.\nfn a() {}\n"));
        assert!(!marked(LanguageType::Python, "x = '@generated'\n"));
        assert!(!marked(rust, ""));
    }

    struct TempRoot(PathBuf);

    impl TempRoot {
        fn new(tag: &str) -> Self {
            let dir = std::env::temp_dir().join(format!(
                "tree-tui-gen-{tag}-{}-{:?}",
                std::process::id(),
                std::thread::current().id()
            ));
            let _ = std::fs::remove_dir_all(&dir);
            std::fs::create_dir_all(&dir).unwrap();
            Self(dir)
        }

        fn write(&self, rel: &str, body: &str) -> PathBuf {
            let path = self.0.join(rel);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(&path, body).unwrap();
            PathBuf::from(rel)
        }
    }

    impl Drop for TempRoot {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }

    #[test]
    fn gitattributes_linguist_generated() {
        let root = TempRoot::new("attrs");
        let files = vec![
            root.write(
                ".gitattributes",
                "# generated code\n*.pb.go linguist-generated\nvendor/** linguist-generated=true\nvendor/keep.go -linguist-generated\n*.md text\n!negated linguist-generated\n",
            ),
            root.write(
                "sub/.gitattributes",
                "*.pb.go linguist-generated=false\ngen/* linguist-generated\n",
            ),
        ];
        let attrs = GitAttributes::load(&root.0, &files);
        let generated = |rel: &str| attrs.is_generated(&root.0, Path::new(rel));

        assert!(generated("api/x.pb.go"));
        assert!(generated("vendor/lib/a.go"));
        assert!(
            !generated("vendor/keep.go"),
            "a later unset wins in its file"
        );
        assert!(
            !generated("sub/y.pb.go"),
            "a deeper file overrides the root"
        );
        assert!(generated("sub/gen/z.rs"));
        assert!(!generated("src/main.rs"));
        assert!(
            !generated("README.md"),
            "other attributes are not generated"
        );
        assert!(
            !generated("negated"),
            "negative patterns are not gitattributes"
        );
    }

    /// An explicit unset overrides a header marker or a lockfile name, as on
    /// GitHub; any value but `false` sets; the last attribute on a line wins;
    /// a `.gitattributes` in a sibling directory does not apply.
    #[test]
    fn gitattributes_precedence_and_values() {
        use super::is_generated;
        let root = TempRoot::new("precedence");
        let files = vec![
            root.write(
                ".gitattributes",
                "vendored.pb.go -linguist-generated\npackage-lock.json !linguist-generated\n*.out linguist-generated=1\nboth.rs linguist-generated -linguist-generated\n",
            ),
            root.write("a/.gitattributes", "*.rs linguist-generated\n"),
        ];
        let attrs = GitAttributes::load(&root.0, &files);
        let header = b"// Code generated by protoc. DO NOT EDIT.\npackage pb\n";
        let generated = |rel: &str, lang, text: &[u8]| {
            is_generated(&attrs, &root.0, Path::new(rel), lang, text)
        };
        assert!(!generated("vendored.pb.go", LanguageType::Go, header));
        assert!(generated("other.pb.go", LanguageType::Go, header));
        // A pattern without a slash matches at any depth, as in git.
        assert!(!generated("package-lock.json", LanguageType::Json, b"{}\n"));
        assert!(!generated(
            "web/package-lock.json",
            LanguageType::Json,
            b"{}\n"
        ));
        assert!(generated(
            "web/pnpm-lock.yaml",
            LanguageType::Yaml,
            b"a: 1\n"
        ));
        assert!(attrs.is_generated(&root.0, Path::new("x.out")));
        assert!(!attrs.is_generated(&root.0, Path::new("both.rs")));
        assert!(attrs.is_generated(&root.0, Path::new("a/x.rs")));
        assert!(
            !attrs.is_generated(&root.0, Path::new("b/x.rs")),
            "a sibling's rules"
        );
    }

    /// A directory pattern applies to directories, not the files in them —
    /// as in git, `vendor/` alone marks nothing; `vendor/**` does.
    #[test]
    fn a_directory_pattern_marks_no_files() {
        let root = TempRoot::new("dirpat");
        let files = vec![root.write(".gitattributes", "vendor/ linguist-generated\n")];
        let attrs = GitAttributes::load(&root.0, &files);
        assert!(!attrs.is_generated(&root.0, Path::new("vendor/a.go")));
    }

    #[test]
    fn no_gitattributes_marks_nothing() {
        let root = TempRoot::new("none");
        let attrs = GitAttributes::load(&root.0, &[]);
        assert!(!attrs.is_generated(&root.0, Path::new("a.rs")));
    }
}
